-- =============================================================================
-- CYBERVERSE 3D GAMING STORE - SCHEMA POSTGRES PARA SUPABASE
-- =============================================================================
-- Cómo usarlo:
-- 1. Crea un proyecto en https://supabase.com (Free tier basta)
-- 2. Ve a SQL Editor > New query > pega TODO este archivo > Run
-- 3. Luego ve a Table Editor y verifica que existan las 19 tablas
--
-- Notas de migración MySQL -> Postgres/Supabase:
-- - AUTO_INCREMENT -> GENERATED BY DEFAULT AS IDENTITY
-- - ENUM(...) -> TEXT + CHECK
-- - TINYINT(1) -> BOOLEAN
-- - DATETIME -> TIMESTAMPTZ
-- - Se agrega tabla sesiones_log (la usaba api/login.php pero no existía)
-- =============================================================================

-- Extensión para generar UUIDs (ids tipo 'usr-uuid-xxxx')
create extension if not exists "pgcrypto";

-- -----------------------------------------------------------------------------
-- 1. MÓDULO DE USUARIOS Y AUTENTICACIÓN
-- -----------------------------------------------------------------------------

create table if not exists usuarios (
  id text primary key default ('usr-uuid-' || floor(random()*90000+10000)::text),
  nombre_completo varchar(120) not null,
  email varchar(150) not null unique,
  password_hash varchar(255) not null,
  telefono varchar(20),
  rol text not null default 'CLIENTE' check (rol in ('CLIENTE','ADMIN','SOPORTE')),
  estado text not null default 'ACTIVO' check (estado in ('ACTIVO','INACTIVO','SUSPENDIDO')),
  fecha_registro timestamptz not null default now(),
  ultima_conexion timestamptz
);

create table if not exists direcciones_facturacion (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  usuario_id text not null references usuarios(id) on delete cascade,
  pais varchar(60) not null default 'Colombia',
  departamento_estado varchar(60) not null,
  ciudad varchar(60) not null,
  direccion_linea1 varchar(150) not null,
  direccion_linea2 varchar(150),
  codigo_postal varchar(15),
  es_predeterminada boolean not null default true
);

-- Log de inicios de sesión (lo usa login.js / login.php)
create table if not exists sesiones_log (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  usuario_id text references usuarios(id) on delete set null,
  email_ingresado varchar(150),
  ip_cliente varchar(45),
  resultado text,
  mensaje varchar(255),
  fecha timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- 2. CATÁLOGO
-- -----------------------------------------------------------------------------

create table if not exists categorias (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  codigo varchar(50) not null unique,
  nombre varchar(80) not null,
  descripcion text,
  activo boolean not null default true
);

create table if not exists plataformas (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  codigo varchar(30) not null unique,
  nombre varchar(60) not null,
  icono_class varchar(50)
);

create table if not exists productos (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  categoria_id bigint not null references categorias(id) on delete restrict,
  titulo varchar(150) not null,
  slug varchar(160) not null unique,
  descripcion text not null,
  precio_cop numeric(12,2) not null check (precio_cop >= 0),
  precio_original_cop numeric(12,2),
  rating_promedio numeric(3,2) not null default 5.00 check (rating_promedio between 0 and 5),
  total_resenas int not null default 0,
  badge varchar(50),
  imagen_url varchar(1024) not null,
  destacado boolean not null default false,
  activo boolean not null default true,
  req_os varchar(100),
  req_gpu varchar(150),
  req_ram varchar(50),
  req_storage varchar(50),
  fecha_creacion timestamptz not null default now(),
  fecha_actualizacion timestamptz not null default now()
);

create table if not exists producto_plataformas (
  producto_id bigint not null references productos(id) on delete cascade,
  plataforma_id bigint not null references plataformas(id) on delete cascade,
  primary key (producto_id, plataforma_id)
);

create table if not exists licencias_digitales (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  producto_id bigint not null references productos(id) on delete restrict,
  plataforma_id bigint not null references plataformas(id) on delete restrict,
  clave_activacion varchar(255) not null unique,
  estado text not null default 'DISPONIBLE' check (estado in ('DISPONIBLE','ASIGNADA','REVOCADA')),
  fecha_carga timestamptz not null default now(),
  fecha_asignacion timestamptz
);

-- -----------------------------------------------------------------------------
-- 3. DESCUENTOS Y CARRITO (carrito se sigue guardando en localStorage del front)
-- -----------------------------------------------------------------------------

create table if not exists cupones (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  codigo varchar(30) not null unique,
  tipo_descuento text not null check (tipo_descuento in ('PORCENTAJE','MONTO_FIJO')),
  valor_descuento numeric(12,2) not null check (valor_descuento > 0),
  monto_minimo_compra numeric(12,2) default 0.00,
  usos_maximos int default 1000,
  usos_actuales int not null default 0,
  fecha_inicio timestamptz not null default now(),
  fecha_expiracion timestamptz not null,
  activo boolean not null default true
);

create table if not exists carritos (
  id text primary key,
  usuario_id text references usuarios(id) on delete cascade,
  fecha_creacion timestamptz not null default now(),
  fecha_actualizacion timestamptz not null default now()
);

create table if not exists carrito_items (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  carrito_id text not null references carritos(id) on delete cascade,
  producto_id bigint not null references productos(id) on delete cascade,
  plataforma_id bigint not null references plataformas(id) on delete restrict,
  cantidad int not null default 1 check (cantidad > 0),
  fecha_agregado timestamptz not null default now(),
  unique (carrito_id, producto_id, plataforma_id)
);

-- -----------------------------------------------------------------------------
-- 4. ÓRDENES Y PASARELA
-- -----------------------------------------------------------------------------

create table if not exists metodos_pago (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  codigo varchar(50) not null unique,
  nombre varchar(100) not null,
  descripcion varchar(255),
  icono_class varchar(50),
  activo boolean not null default true
);

create table if not exists ordenes (
  id text primary key,
  codigo_referencia varchar(30) not null unique,
  usuario_id text not null references usuarios(id) on delete restrict,
  cupon_id bigint references cupones(id) on delete set null,
  subtotal_cop numeric(12,2) not null check (subtotal_cop >= 0),
  descuento_cop numeric(12,2) not null default 0.00 check (descuento_cop >= 0),
  impuesto_cop numeric(12,2) not null default 0.00 check (impuesto_cop >= 0),
  total_cop numeric(12,2) not null check (total_cop >= 0),
  moneda_compra text not null default 'COP' check (moneda_compra in ('COP','USD','EUR','MXN')),
  total_moneda_original numeric(12,2) not null,
  tasa_cambio numeric(10,4) not null default 1.0000,
  estado text not null default 'PENDIENTE' check (estado in ('PENDIENTE','PAGADA','PROCESANDO','COMPLETADA','CANCELADA','REEMBOLSADA')),
  fecha_creacion timestamptz not null default now(),
  fecha_actualizacion timestamptz not null default now()
);

create table if not exists orden_detalles (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  orden_id text not null references ordenes(id) on delete cascade,
  producto_id bigint not null references productos(id) on delete restrict,
  plataforma_id bigint not null references plataformas(id) on delete restrict,
  licencia_id bigint unique references licencias_digitales(id) on delete set null,
  cantidad int not null default 1 check (cantidad > 0),
  precio_unitario_cop numeric(12,2) not null,
  subtotal_cop numeric(12,2) not null
);

create table if not exists transacciones_pago (
  id text primary key,
  orden_id text not null references ordenes(id) on delete cascade,
  metodo_pago_id bigint not null references metodos_pago(id) on delete restrict,
  referencia_pasarela varchar(100) not null,
  monto numeric(12,2) not null check (monto >= 0),
  moneda varchar(3) not null default 'COP',
  estado_transaccion text not null check (estado_transaccion in ('APROBADA','PENDIENTE','RECHAZADA','FALLIDA','REEMBOLSADA')),
  codigo_respuesta varchar(50),
  mensaje_respuesta varchar(255),
  ip_cliente varchar(45),
  fecha_transaccion timestamptz not null default now()
);

create table if not exists detalles_pago_tarjeta (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  transaccion_id text not null unique references transacciones_pago(id) on delete cascade,
  nombre_titular varchar(120) not null,
  marca_tarjeta varchar(30) not null,
  ultimos_cuatro varchar(4) not null,
  mes_expiracion varchar(2) not null,
  anio_expiracion varchar(4) not null,
  token_transaccion varchar(255) not null
);

create table if not exists detalles_pago_alternativo (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  transaccion_id text not null unique references transacciones_pago(id) on delete cascade,
  proveedor varchar(50) not null,
  identificador_cuenta varchar(150),
  codigo_convenio varchar(50)
);

-- -----------------------------------------------------------------------------
-- 5. RESEÑAS Y AUDITORÍA
-- -----------------------------------------------------------------------------

create table if not exists resenas (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  producto_id bigint not null references productos(id) on delete cascade,
  usuario_id text not null references usuarios(id) on delete cascade,
  calificacion int not null check (calificacion between 1 and 5),
  comentario text not null,
  compra_verificada boolean not null default true,
  fecha_resena timestamptz not null default now(),
  unique (producto_id, usuario_id)
);

create table if not exists auditoria_estados_orden (
  id bigint GENERATED BY DEFAULT AS IDENTITY primary key,
  orden_id text not null references ordenes(id) on delete cascade,
  estado_anterior varchar(30),
  estado_nuevo varchar(30) not null,
  usuario_modificador_id text references usuarios(id) on delete set null,
  motivo varchar(255),
  fecha_cambio timestamptz not null default now()
);

-- -----------------------------------------------------------------------------
-- 6. ÍNDICES
-- -----------------------------------------------------------------------------
create index if not exists idx_productos_categoria on productos(categoria_id);
create index if not exists idx_ordenes_usuario on ordenes(usuario_id);
create index if not exists idx_ordenes_estado on ordenes(estado);
create index if not exists idx_transacciones_orden on transacciones_pago(orden_id);
create index if not exists idx_licencias_producto_estado on licencias_digitales(producto_id, estado);
create index if not exists idx_resenas_producto on resenas(producto_id);

-- -----------------------------------------------------------------------------
-- 7. ROW LEVEL SECURITY (RLS)
-- -----------------------------------------------------------------------------
-- Estrategia Fase 1 (migración rápida): el frontend NO habla directo a la DB,
-- solo habla a /api/* (Vercel Functions con SERVICE_ROLE). Por eso bloqueamos
-- acceso directo anon y dejamos que el service_role opere.
-- En Supabase, service_role bypasea RLS automáticamente, así que basta con
-- habilitar RLS sin crear policies abiertas.

alter table usuarios enable row level security;
alter table direcciones_facturacion enable row level security;
alter table sesiones_log enable row level security;
alter table categorias enable row level security;
alter table plataformas enable row level security;
alter table productos enable row level security;
alter table producto_plataformas enable row level security;
alter table licencias_digitales enable row level security;
alter table cupones enable row level security;
alter table carritos enable row level security;
alter table carrito_items enable row level security;
alter table metodos_pago enable row level security;
alter table ordenes enable row level security;
alter table orden_detalles enable row level security;
alter table transacciones_pago enable row level security;
alter table detalles_pago_tarjeta enable row level security;
alter table detalles_pago_alternativo enable row level security;
alter table resenas enable row level security;
alter table auditoria_estados_orden enable row level security;

-- Lectura pública del catálogo (para poder mostrar productos sin login si a
-- futuro consultas directo desde el front con anon key). Si solo usarás /api/*,
-- estas policies son opcionales pero no estorban.
drop policy if exists "catalogo publico" on productos;
create policy "catalogo publico" on productos for select using (true);
drop policy if exists "categorias publicas" on categorias;
create policy "categorias publicas" on categorias for select using (true);
drop policy if exists "plataformas publicas" on plataformas;
create policy "plataformas publicas" on plataformas for select using (true);
drop policy if exists "metodos publicos" on metodos_pago;
create policy "metodos publicos" on metodos_pago for select using (true);
drop policy if exists "cupones publicos" on cupones;
create policy "cupones publicos" on cupones for select using (true);
